names as (select distinct symbol as sym from deriv_metrics_daily),
am_syms as (select distinct upper(symbol) as sym from asset_mcap_daily where source='coingecko_pro_market_chart'),
px as (select upper(a.symbol) as sym, a.d, a.price, a.mcap, 1 as mult from asset_mcap_daily a where a.source='coingecko_pro_market_chart' and upper(a.symbol) in (select sym from names)
  union all select p.symbol, c.d, c.price, c.mcap, p.mult from perp_cg_map p join cg_coin_mcap_daily c on c.coin_id=p.coin_id where p.verdict='resolved' and p.symbol not in (select sym from am_syms)),
oi as (select symbol as sym, d, oi_value_close, oi_close from deriv_metrics_daily),
chk as (select o.sym, count(*) n_overlap, percentile_cont(0.5) within group (order by abs(x.price*x.mult/(o.oi_value_close/o.oi_close)-1)) med_err
  from oi o join px x on x.sym=o.sym and x.d=o.d where o.d >= '2023-01-01' and o.oi_close>0 and o.oi_value_close>0 and x.price>0 group by o.sym),
kept as (select sym from chk where n_overlap>=30 and med_err<=0.05),
cs as (select o.sym, o.d, o.oi_value_close/x.mcap as r, ln(x.mcap) as size from oi o join kept using (sym) join px x on x.sym=o.sym and x.d=o.d
  where o.d in (select distinct d::date from tk) and o.oi_value_close>0 and x.mcap>=20000000),
rk as (select sym, d, rank() over (partition by d order by r) + (count(*) over (partition by d, r)-1)/2.0 as rr,
  rank() over (partition by d order by size) + (count(*) over (partition by d, size)-1)/2.0 as rs, count(*) over (partition by d) n from cs),
fit as (select *, regr_slope(rr, rs) over (partition by d) b, regr_intercept(rr, rs) over (partition by d) a from rk),
res as (select sym, d, n, rr - (a + b*rs) as e from fit),
pc as (select sym, d, n, percent_rank() over (partition by d order by e) as p from res)
select string_agg(t.sym||'|'||t.d||'|'||coalesce(round(pc.p::numeric,5)::text,'')||'|'||coalesce(pc.n::text,'')||'|'||(t.sym in (select sym from kept))::text, ';' order by t.d, t.sym)
from tk t left join pc on pc.sym=t.sym and pc.d=t.d::date;
